-- Each gallery thumbnail follows the same source as the unit it opens.
UPDATE tours SET thumbnail_url = (
  SELECT json_extract(units.gallery, '$[0]') FROM units WHERE units.id = tours.unit_id
)
WHERE deleted_at IS NULL AND unit_id IN (
  SELECT id FROM units WHERE deleted_at IS NULL AND identifier IN ('101','102','201','202','301','302','401','402','501')
);
